// === Tab: mySketch ===
let w = 900,
  h = 900;
let s = 10;
let grid = 30;
let g = 0.5;
let pal = ['#ECAA9C', '#B1D1C6', '#2E5B8B', '#F2CA60', '#d4c7a3', '#DE7830', '#513C2C', '#1F3858', '#C9292E', '#bfb8a3'];

function mousePressed() {
  redraw();
}

function setup() {
  createCanvas(w, h);
  pixelDensity(2);
  noLoop();
  smooth();
  colorMode(HSB, 360, 100, 100, 100);
}

function draw() {
  background(220);
  shuffle(pal, true);
  push();
  rectMode(CORNER);
  stroke(0, 0, 10, 100);
  strokeWeight(1);
  noFill();
  var corner = s * 4;
  var margin = s * 6;
  var size = w - corner * 2 - margin * 2;
  push();
  translate(corner + margin, corner + margin);
  var colorIndex;
  var restX = size;
  while (restX > 0) {
    var vx = int(random(3, 12)) * s;
    if (restX < vx) {
      vx = restX;
    }
    colorIndex = 0;
    var restY = size;
    push();
    while (restY > 0) {
      var vy = int(random(5, 8)) * s;
      if (restY < vy) {
        vy = restY;
      }
      if (colorIndex >= pal.length) {
        colorIndex = 0;
      }
      drawDots(vx, vy, pal[colorIndex]);
      colorIndex++;
      translate(0, vy);
      restY -= vy;
    }
    pop();
    translate(vx, 0);
    restX -= vx;
  }
  pop();
  drawGrids();
  drawFrame();
}
// ------------------------------------- //
// ------------------------------------- //
// ------------------------------------- //
function drawDots(x, y, col) {
  push();
  var ratio, rr, kk, dd;
  var co = col;
  var q = int(random(4, 6));
  var kr = 1;
  stroke(co);
  strokeWeight(1.0);
  rect(0, 0, x, y); // debug
  strokeWeight(1.5);
  var t = random();
  if (t < 0.3) {
    dd = y * random(0.9, 1.1);
    for (let j = 0; j < y; j += 1) {
      push();
      strokeWeight(0.5);
      if (j % q == 0) line(0, j, x, j);
      pop();
      ratio = map(j, 0, dd, 0.6, 0.01);
      for (let i = 0; i < x; i += 1) {
        rr = random();
        if (rr < ratio) {
          kk = random(-kr, kr);
          point(i, j + kk);
        }
      }
    }
  } else if (t < 0.5) {
    dd = y * random(0.9, 1.1);
    for (let j = y; j > 0; j -= 1) {
      push();
      strokeWeight(0.5);
      if (j % q == 0) line(0, j, x, j);
      pop();
      ratio = map(j, dd, 0, 0.6, 0.01);
      for (let i = 0; i < x; i += 1) {
        rr = random();
        if (rr < ratio) {
          kk = random(-kr, kr);
          point(i, j + kk);
        }
      }
    }
  } else if (t < 0.75) {
    dd = x * random(0.7, 1.1);
    for (let j = 0; j < x; j += 1) {
      push();
      strokeWeight(0.5);
      if (j % q == 0) line(j, 0, j, y);
      pop();
      ratio = map(j, 0, dd, 0.6, 0.01);
      for (let i = 0; i < y; i += 1) {
        rr = random();
        if (rr < ratio) {
          kk = random(-kr, kr);
          point(j, i + kk);
        }
      }
    }
  } else {
    dd = x * random(0.7, 1.1);
    for (let j = x; j > 0; j -= 1) {
      push();
      strokeWeight(0.5);
      if (j % q == 0) line(j, 0, j, y);
      pop();
      ratio = map(j, dd, 0, 0.6, 0.01);
      for (let i = 0; i < y; i += 1) {
        rr = random();
        if (rr < ratio) {
          kk = random(-kr, kr);
          point(j, i + kk);
        }
      }
    }
  }
  fill(220);
  noStroke();
  var nv = int(random(10, 40));
  for (let i = 0; i < nv; i++) {
    var cr = random(min(x, y) * 0.1);
    var cx = random(cr, x - cr);
    var cy = random(cr, y - cr);
    circle(cx, cy, cr);
  }
  pop();
}
// ------------------------------------- //
// ------------------------------------- //
// ------------------------------------- //
function drawGrids() {
  stroke(0, 0, 10, 100);
  strokeWeight(1.5);
  noFill();
  var tx = int(w / s);
  var ty = int(h / s);
  for (let i = 0; i < ty; i++) {
    cy = i * s;
    for (let j = 0; j < tx; j++) {
      cx = j * s;
      point(cx, cy);
    }
  }
}

function drawFrame() {
  var s = 10;
  rectMode(CENTER);
  noStroke();
  fill(220);
  rect(s * 2 - 1, h / 2, s * 4, h);
  rect(w - s * 2 + 1, h / 2, s * 4, h);
  rect(w / 2, s * 2 - 1, w, s * 4);
  rect(w / 2, h - s * 2 + 1, w, s * 4);
}

function getColor() {
  var l = pal.length;
  var cc = random();
  var k = 12;
  if (cc < 1 / l) {
    return pal[0];
  } else if (cc < 2 / l - l / k) {
    return pal[1];
  } else if (cc < 3 / l + l / k) {
    return pal[2];
  } else if (cc < 4 / l - l / k) {
    return pal[3];
  } else if (cc < 5 / l + l / k) {
    return pal[4];
  } else if (cc < 6 / l - l / k) {
    return pal[5];
  } else if (cc < 7 / l + l / k) {
    return pal[6];
  } else if (cc < 8 / l - l / k) {
    return pal[7];
  } else if (cc < 9 / l + l / k) {
    return pal[8];
  } else {
    return pal[9];
  }
}

